import {observeWorkSounds} from '/preferences.js';
import {loadingState,loadFailure} from './loading-state.js';
import {dateFields,readDates,readReminders,syncScheduleFields,briefScheduleFields,scheduleStrip,scheduleNav,calendarHTML,remindersHTML,scheduleAction} from './schedule-ui.js';
import {libraryIcon,agentLabel,identityFor} from '/agent-appearance.js';
import {markdown,proseMarkdown,enhanceMarkdown} from '/rich-text.js';
import {openResourcePreview} from './document-preview.js';
import {methodDefaults,methodName,hasPhases,hasSprints,phases} from './work-methods.js';
import {methodFields,readMethod,deliveryHTML,taskMethodFields,flowDialog,verifyDialog,reviewerDialog} from './work-delivery.js';

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={todo:'To do',in_progress:'In progress',blocked:'Blocked',needs_review:'Needs Review',done:'Done',cancelled:'Cancelled',draft:'Draft',active:'Active',completed:'Completed',archived:'Archived'};
const strategies={assigned:'Direct assignment',orchestrator:'Orchestrator leads',team:'Team plans together'};
const status=s=>`<span class="work-status work-status-${s}">${libraryIcon(({todo:'circle',in_progress:'loader',blocked:'circle-alert',needs_review:'eye',done:'circle-check',cancelled:'circle-x',draft:'file-pen-line',active:'play',completed:'circle-check',archived:'archive'})[s]||'circle',13)}${labels[s]||esc(s)}</span>`;
const taskMark=s=>`<span class="work-task-mark work-task-mark-${s}" aria-hidden="true">${libraryIcon(({done:'circle-check',needs_review:'circle-alert',blocked:'circle-alert',cancelled:'circle-x'})[s]||'circle',22)}${s==='in_progress'?'<span class="work-task-orbit"></span>':''}</span>`;
const btn=(action,label,attrs='')=>`<button type="button" data-work="${action}" ${attrs}>${label}</button>`;
const field=(name,label,value='',attrs='')=>`<label>${label}<input name="${name}" value="${esc(value)}" ${attrs}></label>`;
const size=n=>n>=1024*1024?(n/1024/1024).toFixed(1)+' MiB':Math.max(1,Math.round(n/1024))+' KiB';
const stamp=s=>new Date(s).toLocaleString([],{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const fresh=()=>({requestId:crypto.randomUUID(),title:'',kind:'task',instructions:'',acceptance:'',planText:'',strategy:'assigned',changePolicy:'review',orchestratorId:null,participantIds:[],resources:[],links:[],items:[],management:methodDefaults()});

export class WorkBoard {
  constructor(root,{api,project,onChat,onAddAgent,onProfiles,onScheduleSettings,savedState,toast}){
    Object.assign(this,{root,api,project,onChat,onAddAgent,onProfiles,onScheduleSettings,toast});this.view=savedState?.view||'board';this.selected=savedState?.selected;this.draft=savedState?.draft;this.filter='active';this.section='tasks';this.pending=false;
    this.click=e=>{const b=e.target.closest('[data-work]');if(b)this.action(b).catch(error=>this.error(error));};root.addEventListener('click',this.click);root.innerHTML=loadingState('Loading project tasks',{variant:'board',detail:'Gathering briefs, assignments and progress.'});this.refresh().catch(e=>this.error(e));
  }
  async refresh(force=false){
    if(this.disposed||(!force&&this.data&&this.api.canPoll?.()===false))return;
    if(this.pending){await this.pending;if(force)return this.refresh(true);return;}
    if(!this.renderKey)this.root.innerHTML=loadingState('Loading project tasks',{variant:'board',detail:'Gathering briefs, assignments and progress.'});
    this.pending=(async()=>{
      const data=await this.api('work?project='+encodeURIComponent(this.project.path));if(this.disposed)return;this.data=data;
      if(this.selected&&!data.plans.some(p=>p.id===this.selected))this.selected=null;
      if(!this.selected)this.selected=data.plans.find(p=>p.status===this.filter)?.id;
      if(this.selected)this.detail=await this.api(this.route('detail',{planId:this.selected}));else this.detail=null;
      if(this.disposed)return;if(this.detail)observeWorkSounds(this.project.path,[this.detail]);const key=JSON.stringify([data,this.detail,this.filter,this.section]);if(force||key!==this.renderKey){this.renderKey=key;this.render();}
    })();
    try{await this.pending;}catch(error){this.error(error);throw error;}finally{this.pending=null;}
  }
  async openReview(){await this.refresh();const plan=this.data?.plans.find(p=>p.status==='active'&&p.review);if(plan){this.section='tasks';await this.open(plan.id);}}
  async open(id){this.view='board';await this.pending;this.selected=id;await this.refresh(true);if(this.detail){this.filter=this.detail.status;this.render();}}
  route(route,params={}){return 'work/'+route+'?'+new URLSearchParams({project:this.project.path,...params});}
  actor(id){return identityFor(this.data?.agents.find(a=>a.id===id)||{id,role:id?'Former agent':'Unassigned'});}
  owner(id){return id?agentLabel(this.actor(id)):'<span class="work-unassigned">Unassigned</span>';}
  capture(){if(this.dialog?.querySelector('#pack-work-brief'))this.readDraft();const d=this.draft;if(d&&!d.id&&!d.title&&!d.instructions&&!d.acceptance&&!d.planText&&!d.resources.length&&!d.links.length&&!d.participantIds.length&&d.kind==='task'&&d.strategy==='assigned'&&d.changePolicy==='review'&&!d.schedule?.start&&!d.schedule?.due&&!d.schedule?.overrides&&JSON.stringify(d.management)===JSON.stringify(methodDefaults()))this.draft=null;return {selected:this.selected,draft:this.draft,view:this.view};}
  error(error){if(this.disposed)return;if(error&&!this.renderKey&&!this.dialog){this.root.innerHTML=loadFailure('Project tasks couldn’t load',{detail:error.message,retry:'data-work="retry-load"'});return;}const host=this.dialog?.querySelector('.work-error')||this.root.querySelector('.work-error');if(host){host.textContent=error?.message||'';if(error)host.scrollIntoView({block:'nearest'});}else if(error)this.toast(error.message);}
  render(){
    const p=this.detail,oldScroll=this.root.querySelector('.work-detail')?.scrollTop||0;
    const focused=document.activeElement?.closest('[data-work]'),focusKey=focused&&this.root.contains(focused)?[focused.dataset.work,focused.dataset.id]:null;
    const plans=this.data.plans.filter(p=>p.status===this.filter),reviewCount=this.data.plans.filter(p=>p.status==='active').reduce((n,p)=>n+p.review,0);
    if(this.view!=='board'){const scroll=this.root.scrollTop;this.root.innerHTML=scheduleNav(this)+(this.view==='calendar'?calendarHTML(this):remindersHTML(this))+'<p class="work-error" role="status"></p>';this.root.scrollTop=scroll;if(focusKey)[...this.root.querySelectorAll('[data-work]')].find(b=>b.dataset.work===focusKey[0]&&b.dataset.id===focusKey[1])?.focus({preventScroll:true});return;}
    this.root.innerHTML=`${scheduleNav(this)}<div class="work-toolbar"><div><p>A clear brief. A shared plan. Visible progress.</p>${reviewCount?`<span class="work-review-count">${libraryIcon('eye',14)} ${reviewCount} needing review</span>`:''}</div><div>${this.draft?btn('compose','Resume unsaved brief'):''}${btn('new',libraryIcon('plus',16)+' New task or plan','class="primary"')}</div></div><div class="work-layout"><aside class="work-directory" aria-label="Project briefs"><div class="work-filters" role="group" aria-label="Filter project briefs">${['active','draft','completed','archived'].map(s=>btn('filter',`${labels[s]} <span>${this.data.plans.filter(p=>p.status===s).length}</span>`,`data-id="${s}" aria-pressed="${s===this.filter}"`)).join('')}</div><div class="work-brief-list">${plans.map(p=>btn('select',`<span class="work-brief-kind">${libraryIcon(p.kind==='plan'?'list-tree':'clipboard-list',15)} ${p.kind==='plan'?'Plan':'Task'} ${p.review?`<em>${p.review} to review</em>`:''}</span><strong>${esc(p.title)}</strong><span class="work-list-progress"><span>${p.done}/${p.total} done</span>${p.blocked?`<span>${p.blocked} blocked</span>`:''}</span><progress max="${p.total||1}" value="${p.done}" aria-label="${esc(p.title)} completion"></progress>`,`class="work-brief-card" data-id="${p.id}" aria-pressed="${p.id===this.selected}"`)).join('')||`<p class="work-list-empty">No ${this.filter==='active'?'active work':labels[this.filter].toLowerCase()+' briefs'} yet.</p>`}</div></aside><section class="work-detail" aria-label="Selected brief">${p?this.detailHTML(p):this.emptyHTML()}</section></div><p class="work-error" role="status"></p>`;
    this.root.querySelector('.work-detail').scrollTop=oldScroll;if(focusKey)[...this.root.querySelectorAll('[data-work]')].find(b=>b.dataset.work===focusKey[0]&&b.dataset.id===focusKey[1])?.focus({preventScroll:true});if(p)enhanceMarkdown(this.root,()=>{},{project:this.project.path}).catch(()=>{});
  }
  emptyHTML(){return `<div class="work-empty"><span class="work-empty-mark">${libraryIcon('route',34)}</span><span class="eyebrow">FROM AN IDEA TO ASSIGNED WORK</span><h2>Give your team a direction.</h2><p>Bring a quick request or a full plan. Add the context, choose the team, and decide how they should work together.</p><div class="work-empty-steps"><span>${libraryIcon('paperclip',20)} Files, images & repo references</span><span>${libraryIcon('users',20)} Direct, orchestrated, or shared</span><span>${libraryIcon('list-checks',20)} Tasks, approvals & progress</span></div>${btn('new','Create your first brief →','class="primary"')}${!this.data.agents.length?btn('add-agent','Add a project agent'):''}</div>`;}
  detailHTML(p){
    const total=p.items.filter(t=>t.status!=='cancelled').length,done=p.items.filter(t=>t.status==='done').length,proposals=p.proposals.filter(c=>c.status==='pending'),editable=['draft','active'].includes(p.status);
    const pending=p.outbox.filter(e=>e.state==='pending'),failed=pending.find(e=>e.error),queued=p.deliveries.filter(e=>e.delivery==='queued').length,uncertain=p.deliveries.some(e=>e.delivery==='uncertain'),delivered=p.deliveries.filter(e=>e.delivery==='delivered').length;
    return `<header class="work-detail-head"><div>${status(p.status)}<h2>${esc(p.title)}</h2><p>${p.management?esc(methodName(p.management))+' · ':''}${strategies[p.strategy]} <span>·</span> ${p.changePolicy==='review'?'Task changes need your review':'Agents manage tasks'}</p></div><div class="work-head-actions">${p.status==='draft'?btn('edit-brief','Edit brief')+btn('review-start','Review & start','class="primary"'):p.status==='archived'||p.status==='completed'?btn('restore','Restore plan'):btn('complete','Complete plan',`class="primary" ${!p.items.length||p.items.some(t=>!['done','cancelled'].includes(t.status))||proposals.length||p.flow?.activeSprintId||hasPhases(p.management)&&p.flow.phaseIndex<phases.length?'disabled title="Finish tasks, review proposals, and close sprints or phase gates in Delivery first"':''}`)}${p.status!=='archived'?btn('archive',libraryIcon('archive',16),'aria-label="Archive plan" title="Archive plan"'):''}</div></header>${scheduleStrip(p)}<div class="work-team-line">${p.participantIds.map(id=>this.owner(id)).join('')||'<span>No agents assigned yet</span>'}</div><div class="work-progress"><div><strong>${done}<span> / ${total}</span></strong><span>tasks done</span><small>${p.management?'Independently verified progress':'Progress reported by the team'}</small></div><progress max="${total||1}" value="${done}" aria-label="Plan completion"></progress></div>${p.startedAt?`<div class="work-delivery ${failed||uncertain?'has-error':''}">${libraryIcon(failed||uncertain?'circle-alert':'send',15)}<span>${failed?esc(failed.error):uncertain?'Delivery is uncertain. Inspect the agent chat before sending another message.':pending.length?'Preparing brief delivery…':queued?`${queued} message${queued===1?'':'s'} queued · delivered when agents are ready`:`${delivered} message${delivered===1?'':'s'} delivered`}. Delivery is separate from task progress.</span>${p.threadId?btn('chat','Open team chat →'):p.participantIds.length===1?btn('agent-chat','Open agent →',`data-id="${p.participantIds[0]}"`):''}</div>`:'<p class="work-draft-note">Private draft · No agent has been notified. Review it before starting work.</p>'}<nav class="work-sections" aria-label="Brief sections">${[['tasks','Tasks',p.items.length],['brief','Brief & resources',p.resources.length+p.links.length],['delivery','Delivery',p.flow?.sprints.length||0],['activity','Activity',p.audit.length]].map(([id,label,count])=>btn('section',label+` <span>${count}</span>`,`data-id="${id}" aria-pressed="${this.section===id}"`)).join('')}</nav>${this.section==='tasks'?`${proposals.length?`<section class="work-proposals" aria-label="Pending task changes"><h3>${libraryIcon('git-pull-request',18)} Changes for your review <span>${proposals.length}</span></h3>${proposals.map(q=>`<article><div><strong>${esc(q.operation==='schedule'?'Plan dates':q.operation==='create'?'New task: '+q.input.title:'Update: '+(q.input.title||p.items.find(t=>t.id===q.itemId)?.title||'Task'))}</strong><small>Proposed by ${esc(this.actor(q.actorId).role||q.actorName)}</small><dl>${Object.entries(q.input).map(([k,v])=>`<dt>${({ownerId:'Owner',dependsOn:'Dependencies',parentId:'Parent task',note:'Progress note'})[k]||esc(k)}</dt><dd>${k==='ownerId'?this.owner(v):esc(k==='dependsOn'?(v.map(id=>p.items.find(t=>t.id===id)?.title||id).join(', ')||'None'):k==='parentId'?(p.items.find(t=>t.id===v)?.title||'None'):typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl></div><footer>${btn('reject','Reject',`data-id="${q.id}"`)}${btn('approve','Approve change',`class="primary" data-id="${q.id}"`)}</footer></article>`).join('')}</section>`:''}<div class="work-task-heading"><h3>Task list</h3>${editable?btn('new-item',libraryIcon('plus',14)+' Add task'):''}</div><div class="work-task-list">${p.items.map(t=>`<article class="work-task-row">${taskMark(t.status)}<div><button class="work-task-title" type="button" data-work="edit-item" data-id="${t.id}">${esc(t.title)}</button>${t.note||t.description?`<div class="work-task-preview markdown" data-file-project="${esc(this.project.path)}" ${t.ownerId?`data-file-task="${esc(t.ownerId)}"`:''}>${markdown(t.note||t.description,{literalHtml:true})}</div>`:''}${t.dependsOn.length||t.parentId?`<small>${t.parentId?'Subtask of '+esc(p.items.find(i=>i.id===t.parentId)?.title)+'. ':''}${t.dependsOn.length?'Depends on '+t.dependsOn.map(id=>esc(p.items.find(i=>i.id===id)?.title)).join(', '):''}</small>`:''}<footer class="work-task-assignees" aria-label="Assigned agent">${this.owner(t.ownerId)}</footer></div><div class="work-task-meta">${status(t.status)}${t.phase?`<small>${esc(t.phase)}</small>`:''}${t.points?`<small>${t.points} pts · ${esc(p.flow?.sprints.find(s=>s.id===t.sprintId)?.name||'Backlog')}</small>`:''}${t.schedule?.due?`<small class="work-task-date">${libraryIcon(t.schedule.milestone?'flag':'calendar',12)} ${esc(t.schedule.due.replace('T',' · '))}</small>`:''}${p.management&&t.status==='needs_review'&&p.status==='active'?btn('verify','Verify',`data-id="${t.id}"`):''}</div>${editable?btn('edit-item',libraryIcon('pencil',15),`data-id="${t.id}" aria-label="Edit ${esc(t.title)}"`):''}</article>`).join('')||'<div class="work-list-empty">No tasks yet. Add them yourself, or let your selected team break down the plan after submission.</div>'}</div>`:this.section==='delivery'?deliveryHTML(this,p):this.section==='brief'?`<div class="work-brief-content"><div class="work-brief-document">${[['Instructions',p.instructions],['Success criteria',p.acceptance],['Full plan',p.planText]].filter(([,text])=>text).map(([title,text])=>`<section class="work-document-section"><h3 class="work-section-heading">${title}</h3><div class="markdown document-markdown">${markdown(text,{document:true})}</div></section>`).join('')}</div><section><h3 class="work-section-heading">Resources <span class="work-resource-count">${p.resources.length+p.links.length}</span></h3><p class="work-note">Attached files and repository references are saved snapshots. Links are passed as references.</p><div class="work-resource-list">${p.resources.map(r=>btn('resource',`${libraryIcon(r.kind==='repository'?'file-code':'paperclip',17)}<span><strong>${esc(r.name)}</strong><small>${r.repoPath?esc(r.repoPath)+' · ':''}${size(r.size)} · ${r.kind==='repository'?'Repo snapshot':'Attachment'}</small></span>${libraryIcon('eye',15)}`,`data-id="${r.id}" aria-label="Preview ${esc(r.name)}"`)).join('')}${p.links.map(l=>`<a href="${esc(l)}" target="_blank" rel="noopener noreferrer">${libraryIcon('link',17)}<span>${esc(l)}</span>${libraryIcon('arrow-up-right',15)}</a>`).join('')}${!p.resources.length&&!p.links.length?'<p>No resources attached.</p>':''}</div></section><footer class="work-export"><span>Shared brief · Revision ${p.revision}</span>${btn('export','Download JSON','data-id="json"')}${btn('export','Download Markdown','data-id="md"')}</footer></div>`:`<ol class="work-audit">${[...p.audit].reverse().map(e=>`<li><span class="work-audit-dot"></span><div><strong>${esc(e.action)}</strong><div class="markdown document-markdown">${proseMarkdown(e.detail)}</div>${e.changes?.length?`<details class="work-audit-changes"><summary>${e.changes.length} changed fields</summary><dl>${e.changes.map(c=>`<dt>${esc(c.field)}</dt><dd>${esc(JSON.stringify(c.before))} → ${esc(JSON.stringify(c.after))}</dd>`).join('')}</dl></details>`:''}<small>${e.actorId==='human'?'You':esc(this.actor(e.actorId).role||e.actorName)} · ${stamp(e.at)}</small></div></li>`).join('')}</ol>`}`;
  }
  async action(b){
    if(this.busy)return;if(await scheduleAction(this,b))return;const a=b.dataset.work,id=b.dataset.id;
    if(a==='retry-load')return this.refresh(true);
    if(a==='new'){this.draft||=fresh();return this.compose();}
    if(a==='compose')return this.compose();
    if(a==='profiles'){this.capture();this.closeDialog();this.render();return this.onProfiles?.();}
    if(a==='delivery')this.section='delivery';
    if(a==='reviewers')return reviewerDialog(this);
    if(a==='verify')return verifyDialog(this,id);
    if(['start-sprint','close-sprint','gate'].includes(a))return flowDialog(this,({'start-sprint':'start_sprint','close-sprint':'close_sprint',gate:'approve_gate'})[a]);
    if(a==='add-agent')return this.onAddAgent();
    if(a==='filter'){this.filter=id;this.selected=this.data.plans.find(p=>p.status===id)?.id;return this.refresh(true);}
    if(a==='select'){this.selected=id;return this.refresh(true);}
    if(a==='section'){this.section=id;return this.render();}
    if(a==='edit-brief'){this.draft={...structuredClone(this.detail),expectedRevision:this.detail.revision};return this.compose();}
    if(a==='review-start')return this.reviewStart(this.detail);
    if(a==='new-item'||a==='edit-item')return this.editItem(id);
    if(a==='chat')return this.onChat(this.detail.threadId);
    if(a==='agent-chat')return this.onChat(null,id);
    if(a==='export')return this.api.download(this.route('export',{planId:this.selected,format:id}),`heloscrum-brief.${id}`);
    if(a==='resource')return this.previewResource(id,b);
    if(a==='download-resource')return this.api.download(b.dataset.route,b.dataset.name);
    if(a==='close'){this.capture();this.closeDialog();this.render();return;}
    if(a==='select-all'){this.readDraft();this.draft.participantIds=this.data.agents.map(a=>a.id);return this.renderCompose();}
    if(a==='add-row'){this.readDraft();this.draft.items.push({title:'',description:'',ownerId:null});return this.renderCompose();}
    if(a==='remove-row'){this.readDraft();this.draft.items.splice(Number(id),1);return this.renderCompose();}
    if(a==='remove-resource'){this.readDraft();this.draft.resources=this.draft.resources.filter(r=>r.id!==id);return this.renderCompose();}
    if(a==='add-reference')return this.addReference();
    if(a==='edit-before-start'){this.draft={...structuredClone(this.detail),expectedRevision:this.detail.revision};return this.compose();}
    if(a==='start')return this.working(async()=>{const p=await this.api('work/start',{project:this.project.path,planId:this.detail.id,expectedRevision:this.detail.revision});this.selected=p.id;this.filter='active';this.draft=null;this.closeDialog();this.toast('Work submitted. Delivery status appears on the plan.',null,{tone:'success'});await this.refresh(true);});
    if(['approve','reject'].includes(a))return this.reviewProposal(id,a);
    if(['archive','restore','complete'].includes(a))return this.stateDialog(({archive:'archived',restore:'active',complete:'completed'})[a]);
  }
  dialogShell(title,body){
    this.closeDialog();this.dialog=document.createElement('dialog');this.dialog.className='work-dialog';this.dialog.setAttribute('aria-label',title);this.dialog.innerHTML=`<header class="work-dialog-head"><span class="work-dialog-mark">${libraryIcon('clipboard-list',24)}</span><div><span class="eyebrow">${esc(this.project.name)} · PROJECT WORK</span><h2>${esc(title)}</h2></div>${btn('close',libraryIcon('x',20),'aria-label="Close task form"')}</header><div class="work-dialog-body">${body}</div><p class="work-error" role="status"></p>`;
    this.dialog.addEventListener('click',this.click);this.dialog.addEventListener('change',e=>syncScheduleFields(e.target.closest('form')));this.dialog.addEventListener('cancel',e=>{e.preventDefault();if(!this.busy){this.capture();this.closeDialog();this.render();}});document.body.append(this.dialog);this.dialog.showModal();enhanceMarkdown(this.dialog).catch(()=>{});
  }
  closeDialog(){this.resourceViewer?.close();this.resourceViewer=null;if(this.dialog){this.dialog.close();this.dialog.remove();this.dialog=null;}}
  async previewResource(id,trigger){
    const resource=this.detail.resources.find(r=>r.id===id);if(!resource)return;
    const route=this.route('resource',{planId:this.selected,resourceId:id});
    this.closeDialog();
    this.resourceViewer=openResourcePreview({
      name:resource.name,location:resource.repoPath||resource.name,label:this.project.name+' · Project Work',
      load:()=>this.api.blob(route),context:{project:this.project.path,...(resource.repoPath?{base:resource.repoPath}:{})},
      trigger:()=>trigger?.isConnected?trigger:[...this.root.querySelectorAll('[data-work="resource"]')].find(b=>b.dataset.id===id),
      onClose:()=>{this.resourceViewer=null;},
    });
    return this.resourceViewer.ready;
  }
  async working(fn){this.busy=true;const host=this.dialog||this.root;host.setAttribute('aria-busy','true');const controls=[...host.querySelectorAll('button,input,textarea,select')].map(e=>[e,e.disabled]);controls.forEach(([e])=>e.disabled=true);try{await fn();}finally{this.busy=false;host.removeAttribute('aria-busy');controls.forEach(([e,disabled])=>{if(e.isConnected)e.disabled=disabled;});}}
  async compose(agentId){
    if(!this.data){await this.refresh();if(!this.data)return;}
    this.draft||=fresh();if(agentId){this.draft.participantIds=[...new Set([...this.draft.participantIds,agentId])];if(this.draft.kind==='task'&&this.draft.items.length)this.draft.items[0].ownerId=agentId;}this.renderCompose();
  }
  options(ids,value,empty='Unassigned'){return `<option value="">${empty}</option>`+ids.map(id=>`<option value="${id}" ${id===value?'selected':''}>${esc(this.actor(id).role)}</option>`).join('');}
  readDraft(){
    const form=this.dialog?.querySelector('#pack-work-brief');if(!form)return;
    const d=Object.fromEntries(new FormData(form));this.draft.schedule={...readDates(form,{validate:false}),overrides:readReminders(form)};this.draft.management=readMethod(form,this.draft.management);Object.assign(this.draft,{title:d.title,instructions:d.instructions,acceptance:d.acceptance,planText:d.planText,kind:d.kind,strategy:d.strategy,changePolicy:d.changePolicy,participantIds:[...form.querySelectorAll('[name=participants]:checked')].map(e=>e.value),orchestratorId:d.orchestratorId||null,links:d.links.split('\n').map(l=>l.trim()).filter(Boolean)});
    if(this.draft.kind==='plan')this.draft.items=[...form.querySelectorAll('.work-plan-row')].map((row,i)=>({...this.draft.items[i],title:row.querySelector('[name=rowTitle]').value,description:row.querySelector('[name=rowDescription]').value,ownerId:row.querySelector('[name=rowOwner]').value||null}));
    else this.draft.items=[{...this.draft.items[0],title:d.title||d.instructions.replace(/^\s*[#>*-]+\s*/,'').split('\n')[0].slice(0,100)||this.draft.resources[0]?.name.replace(/\.[^.]+$/,'')||'Project task',description:d.instructions,ownerId:d.taskOwner||null}];
  }
  renderCompose(){
    const previous=this.dialog?.querySelector('#pack-work-brief'),scroll=previous?this.dialog.querySelector('.work-dialog-body').scrollTop:0;
    const active=previous?.contains(document.activeElement)?{name:document.activeElement.name,value:document.activeElement.value,index:[...previous.elements].filter(e=>e.name===document.activeElement.name).indexOf(document.activeElement)}:null;
    const d=this.draft;this.dialogShell(d.id?'Edit task brief':'Create a task or plan',`<form id="pack-work-brief" class="work-brief-form"><div class="work-form-section"><div class="work-step"><span>1</span><div><h3>What do you want to build?</h3><p>Describe your idea here, or attach a brief below. Add a full plan when you have one.</p></div></div><div class="work-form-pair"><label>Brief type<select name="kind"><option value="task" ${d.kind==='task'?'selected':''}>A task</option><option value="plan" ${d.kind==='plan'?'selected':''}>A plan with multiple tasks</option></select></label>${field('title','Name <small>optional · generated from your instructions</small>',d.title,'maxlength="160" placeholder="e.g. Add customer account settings"')}</div><label>Instructions or idea<textarea name="instructions" maxlength="32000" rows="4" placeholder="Describe the outcome, relevant context, and any constraints…">${esc(d.instructions)}</textarea></label><label>Success criteria <small>optional</small><textarea name="acceptance" rows="2" maxlength="8000" placeholder="What should be true when this is finished?">${esc(d.acceptance)}</textarea></label><div data-plan-section ${d.kind==='plan'?'':'hidden'}><label>Full plan <small>Markdown supported · optional</small><textarea name="planText" rows="5" maxlength="32000" placeholder="Paste your plan here, attach a plan file below, or let your team create one.">${esc(d.planText)}</textarea></label></div></div><div class="work-form-section"><div class="work-step"><span>2</span><div><h3>Bring the context</h3><p>Files and repository references are saved with the brief.</p></div></div><button type="button" name="attachFiles" class="work-file-drop" aria-label="Attach Resource Files" aria-describedby="work-file-limits" title="Choose files, paste them into this form, or drop them here. Up to 30 files, 20 MiB each, 100 MiB total.">${libraryIcon('upload',22)}<strong>Attach Files Or Drop Them Here</strong><span id="work-file-limits">Markdown, documents, images & other files · 20 MiB each · 100 MiB total</span></button><input type="file" name="files" multiple hidden aria-label="Choose Resource Files"><div class="work-upload-status" role="status"></div><div class="work-attached">${(d.resources||[]).map(r=>`<div>${libraryIcon(r.kind==='repository'?'file-code':/\.(png|jpe?g|webp|gif)$/i.test(r.name)?'image':'file',16)}<span><strong>${esc(r.name)}</strong><small>${size(r.size)}${r.repoPath?' · '+esc(r.repoPath):''}</small></span>${btn('remove-resource',libraryIcon('x',14),`data-id="${r.id}" aria-label="Remove ${esc(r.name)}"`)}</div>`).join('')}</div><div class="work-reference-input">${field('repoPath','Reference a repository file','','placeholder="docs/requirements.md"')}${btn('add-reference','Attach snapshot')}</div><label>Resource links <small>one URL per line</small><textarea name="links" rows="2" placeholder="https://…">${esc(d.links.join('\n'))}</textarea></label></div><div class="work-form-section"><div class="work-step"><span>3</span><div><h3>Choose the team</h3><p>Assign existing sessions in this project. Each agent keeps its toolbox and identity.</p></div></div><div class="work-team-heading"><strong>Project agents</strong>${btn('select-all','Select all')}</div><div class="work-agent-picker">${this.data.agents.map(a=>`<label><input type="checkbox" name="participants" value="${a.id}" ${d.participantIds.includes(a.id)?'checked':''}>${this.owner(a.id)}</label>`).join('')||`<p>No active agent sessions here yet. Save a draft, then add an agent from the workspace.</p>`}</div><div class="work-form-pair"><label>How should work be divided?<select name="strategy">${Object.entries(strategies).map(([value,label])=>`<option value="${value}" ${d.strategy===value?'selected':''}>${label}</option>`).join('')}</select></label><label data-orchestrator ${d.strategy==='orchestrator'?'':'hidden'}>Orchestrator<select name="orchestratorId">${this.options(d.participantIds,d.orchestratorId,'Choose an agent')}</select></label><label data-task-owner ${d.kind==='task'?'':'hidden'}>Initial task owner<select name="taskOwner">${this.options(d.participantIds,d.items[0]?.ownerId||(d.participantIds.length===1?d.participantIds[0]:null))}</select></label></div><p class="work-coordination-hint">${d.strategy==='assigned'?'Choose the initial owner of every task. The policy below controls later task and assignment changes.':d.strategy==='orchestrator'?'The orchestrator breaks down the plan and assigns tasks within this team.':'Selected agents coordinate in a group chat and claim work from the shared task list.'}</p><fieldset class="work-policy"><legend>Can agents create tasks and change assignments?</legend><label><input type="radio" name="changePolicy" value="review" ${d.changePolicy==='review'?'checked':''}><span><strong>Ask for my review</strong><small>Proposed scope and assignment changes wait for approval. Progress updates appear immediately.</small></span></label><label><input type="radio" name="changePolicy" value="autonomous" ${d.changePolicy==='autonomous'?'checked':''}><span><strong>Let agents manage tasks</strong><small>Apply changes directly within this team. Every change is recorded in Activity.</small></span></label></fieldset></div>${methodFields(this)}${briefScheduleFields(this)}<div class="work-form-section" data-plan-section ${d.kind==='plan'?'':'hidden'}><div class="work-step"><span>5</span><div><h3>Tasks to start with <small>optional for team planning</small></h3><p>Add assignments now, or let your team break down the plan. Dependencies can be linked on the task board before starting.</p></div></div><div class="work-plan-rows">${(d.kind==='plan'?d.items:[]).map((t,i)=>`<div class="work-plan-row"><span>${i+1}</span><div>${field('rowTitle','Task name',t.title,'maxlength="160" required')}<label>Details<textarea name="rowDescription" rows="2" maxlength="16000">${esc(t.description)}</textarea></label></div><label>Owner<select name="rowOwner">${this.options(d.participantIds,t.ownerId)}</select></label>${btn('remove-row',libraryIcon('x',16),`data-id="${i}" aria-label="Remove task ${i+1}"`)}</div>`).join('')}</div>${btn('add-row',libraryIcon('plus',16)+' Add a task')}</div><footer class="work-form-footer"><span>Drafts never notify agents.</span><button type="submit" name="intent" value="draft">Save draft</button><button type="submit" name="intent" value="review" class="primary">Review & start →</button></footer></form>`);
    const form=this.dialog.querySelector('form');if(active){const matches=[...form.elements].filter(e=>e.name===active.name),target=matches[active.index]||matches[0];target?.focus({preventScroll:true});}else form.elements.title.focus({preventScroll:true});this.dialog.querySelector('.work-dialog-body').scrollTop=scroll;
    form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();this.saveBrief(e.submitter?.value).catch(error=>this.error(error));});
    form.addEventListener('change',e=>{if(this.busy)return;if(e.target.name==='files'){const files=[...e.target.files];e.target.value='';this.upload(files).catch(error=>this.error(error));return;}if(['kind','strategy','participants','method'].includes(e.target.name)){this.readDraft();if(e.target.name==='kind'){this.draft.items=[];}if(e.target.name==='participants')for(const key of ['processLeadId','productOwnerId','qaLeadId'])if(!this.draft.participantIds.includes(this.draft.management?.[key]))this.draft.management[key]=null;this.renderCompose();}});
    const drop=form.querySelector('.work-file-drop');
    drop.addEventListener('click',()=>{if(this.busy)return;const input=form.elements.files;try{if(input.showPicker)input.showPicker();else input.click();}catch{input.click();}});
    drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag-over');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag-over'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag-over');if(!this.busy)this.upload(e.dataTransfer.files).catch(error=>this.error(error));});
    form.addEventListener('paste',e=>{if(e.clipboardData.files.length){e.preventDefault();if(!this.busy)this.upload(e.clipboardData.files).catch(error=>this.error(error));}});
  }
  async upload(files){
    this.readDraft();const list=[...files];if(!list.length)return;
    if(this.draft.resources.length+list.length>30)throw Error('Attach at most 30 files.');
    if(list.some(f=>!f.size||f.size>20*1024*1024))throw Error('Each file must be nonempty and no larger than 20 MiB.');
    if([...list,...this.draft.resources].reduce((n,f)=>n+f.size,0)>100*1024*1024)throw Error('Attachments may total at most 100 MiB.');
    let error;await this.working(async()=>{for(const [i,file] of list.entries()){this.dialog.querySelector('.work-upload-status').textContent=`Uploading ${i+1} of ${list.length}: ${file.name}…`;try{const resource=await this.api.upload(this.route('upload',{name:file.name}),file);this.draft.resources.push(resource);}catch(e){error=e;break;}}});this.renderCompose();if(error)throw error;this.dialog.querySelector('.work-upload-status').textContent=`${list.length} file${list.length===1?'':'s'} attached.`;
  }
  async addReference(){this.readDraft();const path=this.dialog.querySelector('[name=repoPath]').value.trim();if(!path)throw Error('Enter a path relative to the project repository.');if(this.draft.resources.length>=30)throw Error('Attach at most 30 files.');await this.working(async()=>{const r=await this.api('work/reference',{project:this.project.path,path});this.draft.resources.push(r);});this.renderCompose();}
  async saveBrief(intent){
    this.readDraft();const d=this.draft;
    await this.working(async()=>{const payload={...d,project:this.project.path,resourceIds:d.resources.map(r=>r.id),expectedRevision:d.revision||d.expectedRevision};delete payload.resources;delete payload.audit;delete payload.proposals;delete payload.outbox;delete payload.deliveries;delete payload.files;delete payload.agents;
      const p=await this.api('work/draft',payload);this.draft=null;this.selected=p.id;this.detail=p;this.filter='draft';if(intent==='review')this.reviewStart(p);else{this.closeDialog();this.toast('Draft saved. No agents notified.',null,{tone:'success'});}await this.refresh(true);
    });
  }
  reviewStart(p){this.detail=p;const unassigned=p.strategy==='assigned'&&(!p.items.length||p.items.some(t=>!t.ownerId)),invalid=!p.participantIds.length||p.strategy==='orchestrator'&&!p.orchestratorId||unassigned;
    this.dialogShell('Review before starting',`<div class="work-submit-review"><h3>${esc(p.title)}</h3><p>${esc(p.instructions.slice(0,600))}${p.instructions.length>600?'…':''}</p><div class="work-review-team">${p.participantIds.map(id=>this.owner(id)).join('')||'No agents selected'}</div><dl><dt>Delivery approach</dt><dd>${esc(methodName(p.management))}${p.management?' · independent verification for Done':''}</dd>${p.management?`<dt>Goal</dt><dd>${esc(p.management.goal||p.title)}</dd><dt>Process lead</dt><dd>${p.management.processLeadId?this.owner(p.management.processLeadId):'You'}</dd><dt>Delivery settings</dt><dd>${hasSprints(p.management)?p.management.sprintCapacity+' points per sprint · ':''}${hasPhases(p.management)?'Human-approved phase gates':p.management.method==='kanban'?'WIP cap '+p.management.wipLimit:'You start and close sprints'}</dd>`:''}<dt>Coordination</dt><dd>${strategies[p.strategy]}</dd><dt>Task changes</dt><dd>${p.changePolicy==='review'?'Require your review':'Agents manage tasks and assignments'}</dd><dt>Starting tasks</dt><dd>${p.items.length} · ${p.resources.length} attached files · ${p.links.length} link${p.links.length===1?'':'s'}</dd>${p.orchestratorId?`<dt>Orchestrator</dt><dd>${this.owner(p.orchestratorId)}</dd>`:''}</dl><p class="work-submit-note">Starting shares this brief with ${p.participantIds.length} selected agent${p.participantIds.length===1?'':'s'}${p.participantIds.length>1?' and creates a team chat':''}. Work is delivered when their sessions are ready. Offline agents need to be resumed from Projects.</p>${invalid?`<p class="work-validation">${!p.participantIds.length?'Select at least one agent.':p.strategy==='orchestrator'&&!p.orchestratorId?'Choose the orchestrator.':'Assign every starting task, or choose an orchestrator / team planning.'}</p>`:''}<footer>${btn('edit-before-start','Edit brief')}${btn('start',libraryIcon('play',16)+' Start work',`class="primary" ${invalid?'disabled':''}`)}</footer></div>`);
  }
  editItem(itemId){
    const p=this.detail,t=p.items.find(i=>i.id===itemId)||{title:'',description:'',ownerId:null,status:'todo',dependsOn:[],parentId:null,note:''},editable=['draft','active'].includes(p.status);
    this.dialogShell(itemId?'Task details':'Add a task',`<form id="pack-work-item" class="work-item-form">${field('title','Task name',t.title,'required maxlength="160"')}<label>Details<textarea name="description" rows="4" maxlength="16000">${esc(t.description)}</textarea></label><div class="work-form-pair"><label>Owner<select name="ownerId">${this.options(p.participantIds,t.ownerId)}</select></label><label>Status<select name="status">${['todo','in_progress','blocked','needs_review','done','cancelled'].filter(s=>!p.management||s!=='done'||t.status==='done').map(s=>`<option value="${s}" ${s===t.status?'selected':''}>${labels[s]}</option>`).join('')}</select></label></div>${taskMethodFields(p,t)}${dateFields(t.schedule,p.reminders.timeZone)}<label>Progress / evidence<textarea name="note" rows="3" maxlength="4000" placeholder="What changed? Add evidence, blockers, or review notes.">${esc(t.note)}</textarea></label><label>Parent task<select name="parentId"><option value="">No parent task</option>${p.items.filter(i=>i.id!==itemId).map(i=>`<option value="${i.id}" ${i.id===t.parentId?'selected':''}>${esc(i.title)}</option>`).join('')}</select></label><fieldset class="work-dependencies"><legend>Wait for these tasks</legend>${p.items.filter(i=>i.id!==itemId).map(i=>`<label><input type="checkbox" name="dependsOn" value="${i.id}" ${t.dependsOn.includes(i.id)?'checked':''}>${esc(i.title)}</label>`).join('')||'<p>No other tasks yet.</p>'}</fieldset><footer>${btn('close','Close')}${editable?'<button type="submit" class="primary">Save task</button>':''}</footer></form>`);
    const form=this.dialog.querySelector('form');if(t.sprintId&&t.sprintId===p.flow?.activeSprintId){for(const name of ['title','description','acceptance'])form.elements[name].readOnly=true;for(const name of ['points','phase','parentId'])if(form.elements[name])form.elements[name].disabled=true;for(const e of form.querySelectorAll('[name=dependsOn]'))e.disabled=true;const cancelled=form.elements.status.querySelector('[value=cancelled]');if(cancelled)cancelled.disabled=true;}if(!editable)for(const e of form.querySelectorAll('input,select,textarea'))e.disabled=true;form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();const input=Object.fromEntries(new FormData(form));try{input.schedule=readDates(form);}catch(error){this.error(error);return;}if(input.points!==undefined)input.points=input.points?Number(input.points):null;input.dependsOn=[...form.querySelectorAll('[name=dependsOn]:checked')].map(e=>e.value);this.working(async()=>{await this.api('work/task',{...input,project:this.project.path,planId:p.id,itemId,expectedRevision:p.revision,requestId:crypto.randomUUID()});this.closeDialog();this.toast('Task saved: '+input.title,null,{tone:'success'});await this.refresh(true);}).catch(error=>this.error(error));});
  }
  reviewProposal(id,decision){const p=this.detail,q=p.proposals.find(q=>q.id===id);this.dialogShell(decision==='approve'?'Approve task change':'Reject task change',`<form id="pack-work-review" class="work-item-form"><h3>${esc(q.input.title||p.items.find(t=>t.id===q.itemId)?.title||'Task change')}</h3><p>${decision==='approve'?'Apply this proposed change and notify the agent.':'Keep the current task and send your feedback to the agent.'}</p><label>Feedback <small>optional</small><textarea name="reason" rows="3" maxlength="4000"></textarea></label><footer>${btn('close','Cancel')}<button class="primary" type="submit">${decision==='approve'?'Approve change':'Reject change'}</button></footer></form>`);this.dialog.querySelector('form').addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();const reason=e.target.elements.reason.value;this.working(async()=>{await this.api('work/review',{project:this.project.path,planId:p.id,proposalId:id,decision,reason,expectedRevision:p.revision});this.closeDialog();this.toast(decision==='approve'?'Task change approved':'Task change rejected',null,{tone:'success'});await this.refresh(true);}).catch(error=>this.error(error));});}
  stateDialog(state){const p=this.detail;this.dialogShell(state==='archived'?'Archive this plan?':state==='completed'?'Complete this plan?':'Restore this plan?',`<form id="pack-work-state" class="work-item-form"><h3>${esc(p.title)}</h3><p>${state==='archived'?'Keep this brief, resources, and history in Archived. Pending brief messages are cancelled. Already running agent turns continue; interrupt them from Agents if needed.':state==='completed'?'Mark this plan completed and retain its task history and resources.':'Return this plan to the task board. Cancelled messages are not automatically sent again.'}</p><footer>${btn('close','Cancel')}<button type="submit" class="primary">${state==='archived'?'Archive plan':state==='completed'?'Complete plan':'Restore plan'}</button></footer></form>`);this.dialog.querySelector('form').addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();this.working(async()=>{const next=await this.api('work/state',{project:this.project.path,planId:p.id,status:state,expectedRevision:p.revision});this.filter=next.status;this.closeDialog();this.toast(p.title+' · '+({archived:'Plan archived',completed:'Plan completed',active:'Plan restored'})[state],null,{tone:'success'});await this.refresh(true);}).catch(error=>this.error(error));});}
  dispose(){this.disposed=true;this.capture();this.closeDialog();this.root.removeEventListener('click',this.click);}
}
